    "content": "(?<![A-Za-z])(?:Hon\\.-?Prof\\.|Univ\\.-?Prof\\.|Prof\\.|Dr\\.|Mag\\.|MMag\\.|DI\\.|Ing\\.|Bakk\\.\\s+iur\\.|PhD\\.|HR\\s+Ing\\.|Techn\\s+|Dipl\\.-?HTL\\-?Ing\\.|PD\\s+Dr\\.|Priv\\.-?Doz\\.|DDr\\.|KommR\\s+|\u00d6kR\\s+|RgR\\s+|StR\\s+|MedR\\s+|HR\\s+|KzlR\\s+|OMedR\\s+|VetR\\s+|AR\\s+|Vizepr\u00e4sident\\s+|Senatspr\u00e4sident\\s+|Hofrat\\s+|Hofr\u00e4tin\\s+|Hofr\u00e4ts\\s+|Vizepr\u00e4sidentin\\s+|Senatspr\u00e4sidentin\\s+|Dr\\.in)(?:\\s+Dr\\.)?\\s+[A-Z][a-z\u00e4\u00f6\u00fc\u00df\u00e9\u00e8\u00ea\u00eb\u00ef\u00ee\u00f4\u00f9\u00fb\u00fc]+(?:\\s+(?:[A-Z]\\.|\\s+[A-Z][a-z\u00e4\u00f6\u00fc\u00df\u00e9\u00e8\u00ea\u00eb\u00ef\u00ee\u00f4\u00f9\u00fb\u00fc]+|-?[A-Z][a-z\u00e4\u00f6\u00fc\u00df\u00e9\u00e8\u00ea\u00eb\u00ef\u00ee\u00f4\u00f9\u00fb\u00fc]+)*)\\b(?![a-z])",
    "priority": 10,
    "output_template": {
      "text": "$0",
      "start": "$start",
      "end": "$end",
      "type": "person"
    },
    "output_key": "entities",
    "user_feedback": [
      "The rule fails to capture hyphenated names such as Dr. Gabriele Grossgut-Palot\u00e1s. Please allow hyphenated names."
    ]
  }
]
